    for _ in range(n): fn(m,d)
    return (time.perf_counter()-t0)/n*1e6
for name in ['mj_fwdPosition','mj_fwdVelocity','mj_fwdActuation','mj_fwdAcceleration','mj_fwdConstraint','mj_Euler','mj_step']:
