cd /app && test -s model.xml && python3 -u - <<'EOF'
import mujoco, numpy as np, time
base = open('/app/model_ref.xml').read()
FULL = mujoco.mjtState.mjSTATE_FULLPHYSICS

def optblock(inner):
    return base.replace('<compiler autolimits="true"/>',
        '<compiler autolimits="true"/>\n  <option %s/>' % inner)

def flagblock(attrs):
    return base.replace('<compiler autolimits="true"/>',
        '<compiler autolimits="true"/>\n  <option %s><flag contact="disable"/></option>' % attrs)

def build(xml, name):
    p = '/tmp/%s.xml' % name
    open(p, 'w').write(xml)
    return mujoco.MjModel.from_xml_path(p)

def sim(m, seed, T=2.0, trace=False):
    d = mujoco.MjData(m)
    rng = np.random.default_rng(seed)
    d.qpos += rng.normal(0, 0.01, size=d.qpos.shape)
    mujoco.mj_forward(m, d)
    n = int(T / m.opt.timestep)
    mc = 0
    for _ in range(n):
        mujoco.mj_step(m, d)
        if trace and d.ncon > mc:
            mc = d.ncon
    s = np.zeros(mujoco.mj_stateSize(m, FULL))
    mujoco.mj_getState(m, d, s, FULL)
    return s, d, mc

# --- 1) contact statistics on reference over 6 seeds ---
ref = build(base, 'ref')
refstates = {}
maxcon_all = 0
t0 = time.perf_counter()
for s in range(6):
    st, d, mc = sim(ref, s, trace=True)
    refstates[s] = st
    maxcon_all = max(maxcon_all, mc)
tref6 = (time.perf_counter() - t0) / 6
print('REF: time/2s-sim=%.4fs  max ncon over 6 seeds=%d  nq=%d nv=%d neq=%d nbody=%d ngeom=%d'
      % (tref6, maxcon_all, ref.nq, ref.nv, ref.neq, ref.nbody, ref.ngeom))

# --- 2) per-stage timing on reference and on dense+PGS ---
variants = {
    'dense':          optblock('jacobian="dense"'),
    'densePGS':       optblock('jacobian="dense" solver="PGS"'),
    'sparsePGS':      optblock('solver="PGS"'),
    'denseCG':        optblock('jacobian="dense" solver="CG"'),
}
models = {k: build(v, k) for k, v in variants.items()}

def stages(m, label, n=200):
    d = mujoco.MjData(m)
    mujoco.mj_forward(m, d)
    out = []
    for name in ('mj_fwdPosition', 'mj_fwdVelocity', 'mj_fwdConstraint', 'mj_Euler', 'mj_step'):
        fn = getattr(mujoco, name)
        t0 = time.perf_counter()
        for _ in range(n):
            fn(m, d)
        out.append('%s=%.0fus' % (name.replace('mj_', ''), (time.perf_counter() - t0) / n * 1e6))
    print('  stages[%s]: %s' % (label, ' '.join(out)))

stages(ref, 'ref')
stages(models['densePGS'], 'densePGS')

# --- 3) speed + accuracy of variants on 2 seeds ---
print('%-12s %8s %7s %11s %11s %s' % ('variant', 'time', 'ratio', 'maxabs', 'norm', 'fails'))
res = {}
for k, m in models.items():
    ts = []; dmax = 0.0; dnorm = 0.0; fails = []
    for s in (0, 1):
        t0 = time.perf_counter(); st, d, mc = sim(m, s); ts.append(time.perf_counter() - t0)
        diff = st - refstates[s]
        dmax = max(dmax, np.abs(diff).max()); dnorm = max(dnorm, np.linalg.norm(diff))
        if not np.allclose(st, refstates[s], atol=1e-5):
            fails.append(s)
    t = float(np.mean(ts)); res[k] = t
    print('%-12s %8.4f %7.3f %11.2e %11.2e %s' % (k, t, t / tref6, dmax, dnorm, fails))
